-- The Year 7/8 Number & Algebra question bank: 180 questions across 12 topics.
--
-- Generated by `python3 scripts/generate_bank_migration.py --version 13` from
-- content/bank/*.json, and checked by `python3 content/render.py --check`. Do not edit it by hand:
-- edit the JSON and generate the next migration.
--
-- Insert-only. Nothing here updates or deletes a question, an option or a topic's questions, so
-- applying it can never overwrite a question a teacher has edited. It runs after the retire
-- migration that immediately precedes it, which clears the previous bank out of the way; running
-- the sweep after this migration would retire this bank too.
--
-- Every wrong option carries the misconception code it was written to catch, in
-- answer_options.misconception_code (V9). There are 508 of them. The register that defines the
-- codes is content/misconceptions.json; the codes are stored so a wrong answer can be read as a
-- named error rather than only as a wrong number.
--
-- Inserted as origin = 'SEED': this is the bank the app ships with, as opposed to content a
-- teacher writes ('AUTHORED') or imports ('IMPORTED').

-- Topics. `fractions` already exists - it held the prototype's combined Fractions, Decimals &
-- Percentages topic - so it is repurposed for this bank's Fractions topic, keeping its slug and id
-- so any recorded session still resolves. Its old name is replaced only if nobody has changed it.
on conflict(slug) do nothing;

-- The prototype row, repurposed. Guarded on the old name so a teacher's rename is
-- not overwritten.
update topics set name = 'Fractions', description = 'Equivalent fractions, comparing, and adding, subtracting, multiplying and dividing fractions.', sort_order = 5
 where slug = 'fractions' and name = 'Fractions, Decimals & Percentages';

-- The id of the question just inserted, one row at a time. Cleared before each capture, so
-- the subquery below can only ever match one row. `if not exists` because an earlier load
-- migration in the same Flyway run leaves its own temp table on the connection.
create temp table if not exists seed_question (id integer);

-- pv-value-of-2  (band 1, single_choice)
values ((select id from topics where slug = 'place-value'), 'What is the value of the 2 in 5.320?', 'After the point come tenths, then hundredths, then thousandths. In 5.320 the 2 is in the hundredths column, so it is worth 2 hundredths, 0.02. Writing 0.2 puts it in the tenths column, 0.002 puts it in the thousandths column, and 2 puts it in the units column.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-fraction-for-01  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'Which fraction is the same as 0.1?', '0.1 is one tenth, and one tenth is written 1/10. 1/100 is one hundredth and 1/1000 is one thousandth, each ten times smaller. 10/1 is ten, not a tenth. The same value can be written as a decimal or as a fraction.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-error-power-ten  (band 4, single_choice)
values ((select id from topics where slug = 'place-value'), 'Ben works out 0.4 × 100 and writes the answer 0.400. What has he done?', 'Multiplying by 100 moves every digit two columns left, so 0.4 × 100 = 40. Ben wrote extra zeros and left the 4 in the tenths column, so the value stayed at 0.4. Multiplying by 10 gives 4, dividing by 100 gives 0.004, and nothing was rounded.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-mystery-number  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'What number has 7 tenths and 3 hundredths?', 'Tenths come first after the point, so the 7 is first and the 3 is second: 0.73. 0.37 puts the 3 in the tenths column. 7.3 moves the 7 into the units column, ten times too big, and 73 is a hundred times too big.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-bridge-run-distance  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'Dan runs 0.5 km on Monday and 0.45 km on Tuesday. Which day did he run further?', '0.5 is five tenths. 0.45 is four tenths and five hundredths. Compare the tenths first, so Monday is further. 45 is bigger than 5, but it counts hundredths, not tenths. More digits do not make a decimal bigger.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-tick-7-hundredths  (band 2, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every number where the 7 is worth 7 hundredths.', 'After the point the columns are tenths, hundredths, thousandths. In 0.07 the 7 is hundredths, and in 12.074 the 0 holds tenths so the 7 is hundredths again. In 0.7 the 7 is tenths, in 7.02 it is units, and in 0.007 it is thousandths.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-not-power-of-ten  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'Which of these is not a power of 10?', 'A power of 10 is made by multiplying tens. 10 × 10 × 10 × 10 = 10 000, 1 × 10 × 10 × 10 = 1 000 and 10 × 10 = 100 are all powers of 10. 10 + 10 + 10 + 10 = 40 is not. Adding tens is not the same as multiplying them.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-coldest-city  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'One night it was −12 °C in Oslo, −3 °C in Prague and −0.4 °C in Warsaw. Which city was coldest?', 'Coldest means the lowest temperature. On a number line −12 is further left than −3 or −0.4, so Oslo is coldest. −3 is not colder just because 3 is smaller than 12: −12 is further below zero.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-hundreds-in-number  (band 4, single_choice)
values ((select id from topics where slug = 'place-value'), 'How many hundreds are in 43 872?', '43 872 ÷ 100 = 438.72, so there are 438.72 hundreds. 438 counts only the whole hundreds and drops the 72. 8 is just the digit in the hundreds column, and 872 is the last three digits of the number, not a count of hundreds.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-find-between  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'Find a number between 0.6 and 0.61.', '0.605 is bigger than 0.6 and smaller than 0.61. Only naming tenths and hundredths hides the numbers in between: 0.601, 0.602 and 0.605 all fit. 0.6 and 0.61 are the two numbers you started with, not numbers between them. The extra zero in 0.0605 shifts every digit right, so it is smaller than 0.6.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-flour-grams  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'Write 2.05 kg in grams.', 'There are 1 000 g in 1 kg, so 2.05 kg = 2.05 × 1 000 = 2 050 g. The 5 is hundredths of a kilogram, which is 50 g, so 2.05 kg is not 2 kg 5 g. Dropping the point and reading 205 or 250 loses the place of the digits.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-retention-7-hundreds  (band 1, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every number where the 7 is worth 700.', '700 is seven hundreds, so the 7 must be in the hundreds column. It is in 4,782 and 40,782. In 7,482 the 7 is thousands, worth 7,000, and in 4,872 it is tens, worth 70.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-sometimes-more-digits  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'Is a number with more decimal places always larger?', 'Sometimes. 0.45 has more decimal places than 0.4 and is bigger, so it is not never. But 0.45 has more decimal places than 0.5 and is smaller, so it is not always. Compare the columns from the left: tenths, then hundredths, then thousandths.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-work-out-67-times-100  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'A ticket costs £6.70. Work out the cost of 100 tickets.', '£6.70 × 100 = £670: multiplying by 100 moves every digit two columns left, so the 6 goes from units to hundreds. £67 is ten times too small and £6,700 is ten times too big. £6.70 is the price unchanged — writing extra zeros does not multiply.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-not-equal-04  (band 1, single_choice)
values ((select id from topics where slug = 'place-value'), 'Three of these are equal. Which is the odd one out?', 'Zeros after the last digit do not change a decimal, so 0.40, 0.400 and 0.4000 all equal 0.4. 0.04 is the odd one out: the 4 is in the hundredths column, so it is four hundredths, ten times smaller than four tenths.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-cube-of-5  (band 1, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'What is 5³?', '5³ means 5 × 5 × 5 = 125. Multiplying by the index gives 5 × 3 = 15, which is the cube-triple error. Squaring uses only two 5s and gives 25, and writing 53 reads the index as a digit beside the base.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-not-multiple-of-7  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Find the number below that is not a multiple of 7.', '49, 98 and 140 are all multiples of 7: 7 × 7, 7 × 14 and 7 × 20. 75 is not, because 7 × 10 = 70 and 7 × 11 = 77. The 7 times table does not stop at 12 × 7, so the multiples carry on past 84.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-error-square  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Mia writes 3² = 6 and says "you multiply by 2". What has she done?', '3² means 3 × 3 = 9. Mia has done 3 × 2 = 6: the index says how many copies of the base to multiply, not what to multiply the base by. Working out 2³ gives 8, adding gives 5, and the square root of 3 is not a whole number.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-which-is-prime  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Which number is prime?', '29 has no factors other than 1 and itself. 21 = 3 × 7 and 27 = 3 × 9, so they are odd but not prime. 1 is not prime either: a prime has exactly two factors, and 1 has only one.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-tick-product-multiple-10  (band 3, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Find every product below that is a multiple of 10.', 'A product is a multiple of 10 when it contains both a 2 and a 5. 2 × 3 × 5 and 2 × 5 × 7 both do, so both are multiples of 10 — you can see it without working them out. 3 × 5 × 7 has no 2 and 2 × 3 × 7 has no 5, so neither is a multiple of 10.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-prime-factorisation-24  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Which expression shows 24 as a product of prime factors?', 'Every factor in a prime factorisation must itself be prime. 2 × 2 × 2 × 3 uses only primes, and it equals 24. 4 × 6, 2 × 12 and 3 × 8 all equal 24, but none is finished: 4, 6, 12 and 8 are all composite.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-lcm-6-8  (band 3, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'What is the lowest common multiple of 6 and 8?', 'Multiples of 6 are 6, 12, 18, 24, … and multiples of 8 are 8, 16, 24, … so the lowest common multiple is 24. Adding 6 + 8 gives 14, which is not a multiple of either. 48 is a common multiple but not the lowest, and 2 is the highest common factor.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-not-factor-of-30  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'One of these is not a factor of 30. Which one?', '30 ÷ 5 = 6, 30 ÷ 6 = 5 and 30 ÷ 15 = 2, so 5, 6 and 15 are all factors of 30. 30 ÷ 4 = 7.5, which is not exact, so 4 is not a factor.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-prime-over-20  (band 3, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'A number has exactly two factors and is greater than 20. Which could it be?', 'Exactly two factors means prime. 23 has only 1 and 23. 21 = 3 × 7, 25 = 5 × 5 and 27 = 3 × 9, so each has more than two factors. Being odd is not enough to be prime.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-prime-factorisation-90  (band 4, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Which is the complete prime factorisation of 90?', 'Keep factorising until every factor is prime. 90 = 2 × 45 = 2 × 3 × 15 = 2 × 3 × 3 × 5, and 2, 3, 3 and 5 are all prime. The other three all equal 90, but each still contains a composite number (15, 9, 10 or 30), so none is complete.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-sometimes-multiple-4-of-2  (band 3, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Is every multiple of 4 also a multiple of 2?', 'Always, because 4 = 2 × 2: any number built from 4s is also built from 2s. 4, 8, 12, 16, … are all even. A number such as 6 is a multiple of 2 but not of 4, so not every multiple of 2 is a multiple of 4 — but the question asks the other way round.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-bridge-tiles-hcf  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'A rectangular path is 24 tiles long and 18 tiles wide. It is covered exactly with the largest possible square tiles. How many tiles along each side of a square tile?', 'The side of the tile must divide both 24 and 18, and we want the largest such number: the highest common factor. 24 = 2³ × 3 and 18 = 2 × 3², so the HCF is 2 × 3 = 6. 2 and 3 are common factors but not the highest, and 72 is the lowest common multiple.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-non-square  (band 2, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Find the number that is not a square number.', 'Square numbers are made by multiplying a whole number by itself: 16 = 4 × 4, 25 = 5 × 5 and 36 = 6 × 6. 12 is not: it lies between 9 and 16, and no whole number multiplied by itself gives 12.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-retention-not-factor-of-12  (band 1, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Three of these are factors of 12. Which one is not?', 'The factors of 12 are 1, 2, 3, 4, 6 and 12. 12 ÷ 1, 12 ÷ 3 and 12 ÷ 4 are exact, so those are factors; 12 ÷ 5 = 2.4, so 5 is not.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-square-garden  (band 3, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'A square garden has an area of 49 m². How long is one side?', 'The area of a square is side × side, so the side is √49 = 7, because 7 × 7 = 49. A square root is not halving (24.5) or dividing by 3.5 (14). 9 × 9 = 81, which is too big.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- int-subtract-3-8  (band 1, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'What is 3 − 8?', 'Start at 3 and move 8 places left on a number line: 2, 1, 0, −1, … to −5. Taking 8 from 3 gives a negative answer. Swapping the numbers round gives 8 − 3 = 5, which is a different calculation.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- int-subtract-negative  (band 2, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'What is 4 − (−3)?', 'Subtracting −3 moves 3 places to the right, the same as adding 3, so 4 − (−3) = 7. Treating the two minus signs as an ordinary subtraction gives 1. The answer is positive, not −7 or −1.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
