-- int-decimal-product-03-02  (band 2, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'What is 0.3 × 0.2?', '3 × 2 = 6, and both numbers have one decimal place, so the answer has two: 0.06. Adding the digits instead of multiplying gives 0.3 + 0.2 = 0.5. Writing 0.6 moves the point one place too few, and 0.006 one place too many.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- int-error-decimal-point  (band 3, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'Priya works out 0.4 × 0.5 and writes 2.0. What has she done?', '4 × 5 = 20, and there are two decimal places altogether, so 0.4 × 0.5 = 0.20 = 0.2. Priya has found 20 and kept it as 2.0, losing the two decimal places. Adding would give 0.9, and dividing would give 0.8.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- int-error-indices-order  (band 3, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'Amir works out 3 + 2² and gets 25, saying "3 + 2 = 5, then 5² = 25". What has he done?', 'The index applies only to the 2, so 3 + 2² = 3 + 4 = 7. Amir has added first and then squared the whole of 3 + 2. Multiplying 3 by 2² gives 12, and squaring the 3 gives 3² + 2 = 11.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
