-- int-order-of-operations-15-6-4  (band 2, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'Work out 15 + 6 × 4.', 'Multiplication is done before addition: 6 × 4 = 24, then 15 + 24 = 39. Working left to right gives (15 + 6) × 4 = 84. Adding 15 + 6 × 4 as 15 + 6 = 21 then × 4 is the same error.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
