values ((select id from topics where slug = 'integers-and-decimals'), 'Which calculation gives 12?', '6 ÷ 0.5 asks how many halves are in 6, which is 12. 6 × 0.5 halves the 6 to 3, and adding or subtracting 0.5 moves it only a little. Multiplication does not always make a number bigger.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
