-- int-bridge-temperature  (band 2, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'At 6 am the temperature was −4 °C. By noon it had risen 9 °C. By 9 pm it had fallen 6 °C. What was the temperature at 9 pm?', '−4 + 9 = 5, so it was 5 °C at noon. Then 5 − 6 = −1, so it was −1 °C at 9 pm. Adding 9 and 6 and ignoring the sign gives 11, and dropping the minus at the end gives 1.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
