-- int-decimal-sum-plank  (band 3, single_choice)
values ((select id from topics where slug = 'integers-and-decimals'), 'A plank is 5.7 m long. A second plank is 0.4 m longer. How long is the second plank?', 'Line up the decimal points: 5.7 + 0.4 means 5.7 + 0.4 = 6.1. Adding the digits after the point as 7 + 4 = 11 gives 5.11, which treats tenths as if they were ones. 6.11 carries the 1 as a whole as well, and 5.1 forgets it entirely.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
