-- rnd-nearest-hundred  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 3,486 to the nearest hundred.', 'The two hundreds either side are 3,400 and 3,500. 3,486 is 86 above 3,400 and only 14 below 3,500, so it is nearer 3,500. Rounding to 3,490 rounds to the nearest ten instead of the nearest hundred, and 3,000 rounds to the nearest thousand.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
