-- rnd-one-decimal-place  (band 1, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 2.41 to 1 decimal place.', '1 decimal place means one digit after the point. The hundredths digit is 1, which is less than 5, so 2.41 rounds down to 2.4. Rounding up gives 2.5, keeping both digits gives 2.41, and 2 is rounded to the nearest whole number, not to 1 decimal place.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
