-- rnd-not-round-to-03  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Which number does not round to 0.3 when rounded to 1 significant figure?', 'To 1 significant figure the first digit that is not zero is the one that matters, so here it is the tenths digit. 0.27, 0.34 and 0.25 all round to 0.3, but 0.35 is halfway and rounds up to 0.4.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
