-- rnd-27481-2sf  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 27,481 to 2 significant figures.', 'The first two significant figures are 2 and 7. The next digit is 4, which is less than 5, so the 7 stays and the rest become zeros: 27,000. Rounding to 27,500 uses the wrong place, and 28,000 rounds the second digit up when it should not.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-error-repeated-rounding  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Ali rounds 3,472 to 1 significant figure by going 3,472 → 3,470 → 3,500 → 4,000. What has he done wrong?', '3,472 to 1 significant figure is 3,000, because 3,472 is between 3,000 and 4,000 and nearer to 3,000. Ali kept rounding on: each step is correct on its own, but the number to be rounded must be compared with the two thousands, not with the result of the previous rounding.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
