-- rnd-find-number-nearest-10  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'A whole number rounds to 50 to the nearest 10. Which of these could it be?', 'Numbers from 45 to 54 round to 50. 46 is in that range. 44 is nearer 40, 55 is halfway and rounds up to 60, and 60 is a multiple of 10 itself.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
