-- rnd-estimate-quotient  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Which calculation estimates 612 ÷ 28 by rounding each number to 1 significant figure?', '612 → 600 and 28 → 30, so the estimate is 600 ÷ 30 = 20. Rounding 28 down to 20 changes the estimate to 30. 620 ÷ 30 is not rounding to 1 significant figure, and 612 ÷ 28 is the exact calculation: the rounding happens before the division, not after.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-halfway-045  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 0.45 to 1 significant figure.', 'The first significant figure is the 4 in the tenths column. The next digit is 5, which is halfway, so we round up: 0.45 → 0.5. Rounding down gives 0.4, cutting the digits off gives 0.45, and 0.05 treats the leading zero as significant.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-not-round-to-05  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Find the number that does not round to 0.5 to 1 decimal place.', '0.45 rounds up to 0.5 and 0.52 and 0.54 round down to 0.5. 0.55 is halfway and rounds up to 0.6, so it does not round to 0.5.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-not-two-sig-figs  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'One of these does not have exactly 2 significant figures. Which one?', 'Leading zeros never count, so 0.045 has two significant figures (4 and 5), 3.7 has two, and 0.30 has two because the trailing zero after a decimal point counts. 0.0450 has three: 4, 5 and the final 0.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-tick-round-to-4000  (band 4, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick the numbers that round to 4,000 to 1 significant figure.', 'To 1 significant figure compare the number with the two thousands either side. 3,600 and 4,499 are both nearer 4,000. The trap is 3,472: rounding it step by step (to 3,470, then 3,500, then 4,000) reaches 4,000, but it is actually nearer 3,000. 4,500 is halfway and rounds up to 5,000, and 3,400 is nearer 3,000.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-bridge-phone-estimate  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'A phone costs £349. Estimate the cost of 6 of these phones by rounding the price to the nearest hundred.', 'Round the price to the nearest hundred first: £349 → £300. Then 300 × 6 = £1,800. £2,100 rounds the price to the nearest £50, not the nearest hundred; £2,094 is the exact answer, so it is not an estimate; and £3,000 rounds £349 up too far.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-retention-not-round-to-30  (band 1, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Three of these round to 30 to the nearest 10. Which one does not?', '25 is halfway and rounds up to 30, and 26 and 34 round down to 30. 35 is halfway between 30 and 40 and rounds up to 40, so it does not round to 30.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-sometimes-smaller  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Does rounding always make a number smaller?', 'Sometimes. 3,486 rounds to 3,500, which is bigger, and 0.27 rounds to 0.3, which is bigger too, because both round up. 3,472 rounds to 3,000, which is smaller. Rounding goes to the nearer value, so it can go either way.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- frac-add-quarters  (band 1, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 1/4 + 1/4?', 'The denominators are already the same, so add the numerators: 1 + 1 = 2, giving 2/4, which simplifies to 1/2. Adding the denominators as well gives 2/8. Two quarters make a half, not a quarter.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-three-quarters-of-20  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 3/4 of 20?', '20 ÷ 4 = 5 is one quarter, and 3 × 5 = 15 is three of them. Stopping after the division gives 5, multiplying by the numerator only gives 60, and dividing by the fraction instead of multiplying gives 26.67.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-multiply-half-third  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 1/2 × 1/3?', 'Multiply the numerators and the denominators: 1 × 1 = 1 and 2 × 3 = 6, so the answer is 1/6. Notice the answer is smaller than either fraction, because a half of a third is a small piece. Bringing in a common denominator and adding gives 5/6 or 2/3, and adding across gives 2/5, not 1/5.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-error-cancel-subtract  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Ravi simplifies 12/18 by taking 1 off the top and 1 off the bottom to get 11/17. What has he done?', 'Simplifying means dividing the top and the bottom by the same number. 12 and 18 both divide by 6, so 12/18 = 2/3. Subtracting 1 from each leaves 11/17, which is a different fraction, not a simpler name for the same one.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-same-as-three-quarters  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which fraction is the same as 3/4?', 'Multiplying the top and the bottom by the same number gives an equivalent fraction: 3/4 = 6/8. Adding 1 to each gives 4/5, which is a different fraction. 3/5 and 7/8 do not split the same whole in the same place.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-equal-to-five-thirds  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which number is equal to 5/3?', '5/3 means 5 ÷ 3, which is 1 remainder 2, so it is 1 2/3. The fraction bar is not a decimal point, so 5/3 is not 5.3. 3/5 is the reciprocal, and 15 comes from multiplying 5 by 3 instead of dividing.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-reverse-three-fifths  (band 4, single_choice)
values ((select id from topics where slug = 'fractions'), '3/5 of a number is 12. What is the number?', 'If 3/5 of the number is 12, then 1/5 is 12 ÷ 3 = 4, and the whole number is 5 × 4 = 20. Applying 3/5 to 12 again gives 7.2, and multiplying by 3 gives 36; neither finds the whole from the part.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-which-calculation-gives-2  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which calculation gives 2?', '1/2 ÷ 1/4 asks how many quarters fit in a half, which is 2. Multiplying instead gives 1/8, which is much smaller. Adding gives 3/4, and subtracting gives 1/4.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-sometimes-bigger-denominator  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Is a fraction with a bigger denominator always smaller than one with a smaller denominator?', 'Sometimes. With the same numerator, a bigger denominator gives a smaller fraction: 1/3 is smaller than 1/2. But 3/4 is bigger than 1/2 even though 4 is bigger than 2, because the numerators are different. The denominator has to be compared with the numerator.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-bigger-than-a-fifth  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which fraction is bigger than 1/5?', 'With numerator 1, a bigger denominator makes a smaller fraction, so 1/8, 1/10 and 1/20 are all smaller than 1/5. 1/3 is bigger, because thirds are larger pieces than fifths.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-tick-equivalent-half  (band 3, multi_select)
values ((select id from topics where slug = 'fractions'), 'Which fractions are the same as 1/2?', 'Multiplying the top and the bottom by the same number keeps the value: 1/2 = 2/4 = 3/6 = 5/10. 4/6 simplifies to 2/3 and 3/4 is three quarters, so neither is the same as a half.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-smaller-than-half  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which fraction is smaller than 1/2?', 'A fraction is smaller than 1/2 when the numerator is less than half the denominator. 5/12 is less than 6/12, so it is smaller. 3/5, 4/7 and 5/8 all have more than half the denominator on top.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-retention-whole-numbers  (band 1, multi_select)
values ((select id from topics where slug = 'fractions'), 'Put a tick by each fraction equal to 1.', 'When the numerator and the denominator are the same, the whole is split into that many parts and all of them are taken, so the fraction is 1: 2/2, 4/4 and 6/6 all equal 1. 3/1 is 3 wholes and 5/4 is more than 1.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-bridge-recipe-sugar  (band 4, single_choice)
values ((select id from topics where slug = 'fractions'), 'A recipe uses 3/4 of a cup of sugar. Zak makes half the recipe. How much sugar does he use?', 'Half the recipe means half of 3/4: 3/4 × 1/2 = 3/8. The answer is smaller than 3/4, which makes sense for half a recipe. 3/2 doubles it, 1/4 subtracts a half instead of halving, and 3/4 leaves the amount unchanged.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-mixed-from-improper  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'A recipe needs 11/4 cups of milk. Write this as a mixed number.', '11 ÷ 4 = 2 remainder 3, so 11/4 = 2 3/4. 2 1/4 uses the wrong remainder; 3 1/4 has the whole number too big; and 11 4/1 reads the numerator and denominator as separate wholes.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-percent-of-240  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'What is 25% of 240?', '25% is one quarter, and 240 ÷ 4 = 60. Writing 25 treats the percentage as the answer itself. 96 is 40% of 240, not 25%, and 40 comes from dividing by 6 instead of 4.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-increase-80-by-15  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Increase 80 by 15%.', '10% of 80 is 8 and 5% is 4, so 15% is 12. Then 80 + 12 = 92. Adding the 15 straight on gives 95, which is not 15% of 80. 68 takes 15% off, and 12 is only the increase, not the new amount.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-increase-multiplier  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which multiplier increases an amount by 15%?', 'Increasing by 15% leaves the whole amount, 100%, plus another 15%, so the multiplier is 1.15. Multiplying by 0.15 finds only the increase, by 15 makes the amount far too large, and 0.85 decreases the amount by 15%.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-percentage-points  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A pass rate rises from 20% to 25%. By how many percentage points does it rise?', 'The rate itself has risen by 25 − 20 = 5 percentage points. Percentages and percentage points are different measures: 5 points is a rise of 5 out of 100, which as a proportion of the old rate is 25%.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-reverse-discount  (band 4, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'In a sale a coat is reduced by 25% and now costs £45. What was the original price?', '£45 is 75% of the original price, so the original is £45 ÷ 0.75 = £60. Adding 25% of £45 back on gives £56.25, which overshoots because 25% of £45 is less than 25% of the original. Taking another 25% off gives £33.75.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-reverse-increase  (band 4, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A price is increased by 20% and is now £72. What was the price before the increase?', '£72 is 120% of the old price, so the old price is £72 ÷ 1.2 = £60. Taking 20% off £72 gives £57.60, but 20% of £72 is not 20% of the original. £90 would be reached if £72 were the original and it grew again.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-fraction-to-percent  (band 1, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which percentage is equal to 2/5?', '2/5 = 4/10 = 40/100, so it is 40%. 25% is 1/4, not 2/5. 4% comes from taking the numerator alone, and 250% comes from dividing 5 by 2 the wrong way round.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-decimal-to-percent  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which percentage is equal to 0.4?', 'A percentage is a fraction out of 100, so multiply the decimal by 100: 0.4 = 40%. Moving the point one place gives 4%, which is ten times too small; 0.4% is a hundred times too small; and 400% is ten times too big.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-percent-to-decimal  (band 1, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Write 7% as a decimal.', '7% means 7 out of 100, which is 7 ÷ 100 = 0.07. Moving the point one place gives 0.7 (that is 70%), three places gives 0.007, and 7 is the percentage itself, not the decimal.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-bridge-double-discount  (band 4, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A shop takes 20% off a £45 jacket, then takes a further 10% off the sale price. What does the jacket cost now?', 'After 20% off, £45 × 0.8 = £36. Then 10% off £36 is £36 × 0.9 = £32.40. Taking 30% off once gives £31.50, which is not the same because the second 10% is taken from the smaller amount. £36 stops after the first discount, and £24.75 is not a correct combination.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-tick-equal-quarter  (band 3, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Select every number equal to 0.25.', '0.25 is one quarter, so 1/4, 25% and 25/100 all name the same value. 2/5 is 0.4, which is bigger. 0.025 is ten times smaller than 0.25, and it is 2.5%.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- fdp-smaller-than-half  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which number is smaller than 0.5?', '3/5 = 0.6, 55% = 0.55 and 0.6 is already a decimal, so all three are bigger than 0.5. 0.45 is smaller.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-retention-not-equal-half  (band 1, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Spot the number that is not equal to 50%.', '50% is 50 out of 100, which is 0.5, and 0.5 is 1/2 and 5/10. 0.05 is 5%, ten times smaller, so it is not equal to 50%.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-jumper-decrease  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A jumper costs £40. Its price is reduced by 25%. What is the new price?', '25% of £40 is £10, so the new price is £40 − £10 = £30. Subtracting the percentage number gives £15, which takes off 25 pence, not 25%. £35 takes off only 12.5%, and £50 increases the price instead of reducing it.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- fdp-sometimes-double  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Is increasing an amount by 50% the same as doubling it?', 'Never. Increasing by 50% gives the whole amount plus a half, which is 1.5 times the amount. Doubling is 2 times the amount, which is an increase of 100%. The multiplier for +50% is 1.5, not 2.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-red-fraction  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'The ratio of red to blue counters in a box is 2:5. What fraction of the counters are red?', 'The ratio 2:5 compares red with blue, but the question asks about the whole box. There are 2 + 5 = 7 parts, of which 2 are red, so the fraction is 2/7. Writing 2/5 reads the ratio itself as a fraction of the whole, and 5/7 finds the blue fraction.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-recipe-rice  (band 1, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'A recipe for 4 people uses 300 g of rice. How much rice is needed for 10 people?', 'Scale by the same factor: 300 g for 4 people is 75 g each, and 10 × 75 = 750 g. Dividing instead of multiplying gives 120 g. 600 g adds 300 for the extra 6 people as if each extra person needed a whole recipe, and 306 g adds 6 g for 6 people.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-inverse-workers  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Six workers take 4 days to build a wall. How long would 12 workers take, working at the same rate?', 'Twice as many workers take half the time, so 12 workers take 2 days. Treating it as direct proportion gives 8 days: more workers means less time, not more. The total work is the same, so workers × days stays constant.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-share-sweets  (band 1, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Sweets are shared between two children in the ratio 3:2. There are 30 sweets. How many does the first child get?', 'The ratio 3:2 gives 3 + 2 = 5 parts, and 30 ÷ 5 = 6 sweets in each part. The first child gets 3 × 6 = 18. 12 is the second child''s share, 15 is half, and 20 treats the ratio as a difference.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-simplify-units  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Simplify the ratio 40 minutes : 2 hours.', 'Write both in the same unit first: 40 minutes : 120 minutes. Divide both by 40 to get 1:3. Leaving the units different and dividing 40 by 2 gives 20:1, and 40:2 is not simplified at all.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-whole-to-part  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'In a bag, 3/5 of the counters are red. The rest are blue. What is the ratio of red to blue counters?', 'The fraction 3/5 is red out of the whole, so 2/5 is blue. Red to blue is therefore 3:2. 3:5 compares red with the whole rather than with blue, 2:3 reverses the order, and 5:3 reverses both.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-three-part-share  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), '£240 is shared in the ratio 2:3:5. What is the largest share?', 'The parts are 2 + 3 + 5 = 10, so each part is £240 ÷ 10 = £24. The largest share is 5 parts: 5 × £24 = £120. £72 is 3 parts, £48 is 2 parts, and £24 is a single part.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-children-from-adults  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'The ratio of adults to children at a show is 5:3. There are 24 children. How many adults are there?', '3 parts are 24 children, so each part is 24 ÷ 3 = 8. Adults are 5 parts: 5 × 8 = 40. Scaling by 5/3 or dividing by 5 gives the wrong part; 8 is the value of one part, not the number of adults.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-bridge-paint  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Paint is mixed from red and white in the ratio 2:5. Tom uses 600 ml of white paint. How much red paint does he need?', '5 parts of white are 600 ml, so one part is 600 ÷ 5 = 120 ml. Red is 2 parts: 2 × 120 = 240 ml. Multiplying by 5 or halving gives the wrong scaling, and 1,200 ml doubles the white instead of finding the red.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-error-unequal-sharing  (band 4, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Alice and Brenda share money in the ratio 4:3. Alice has £20. Bella halves £20 to get £10, halves again to get £5, and adds to get £15 for Brenda. What has gone wrong?', '4 parts are £20, so one part is £5, and Brenda''s 3 parts are £15 — the answer happens to be right, but the method is not: halving and adding only works because the numbers are convenient. Scaling by 3/4 (£20 × 3/4 = £15) is the multiplicative method that works for any numbers.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-tick-equivalent-2-3  (band 2, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Which ratios are equivalent to 2:3?', 'Multiplying both parts by the same number keeps a ratio equivalent: 2:3 = 4:6 = 6:9 = 10:15. 3:4 and 4:5 come from adding 1 to each part, which changes the ratio.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- ratio-which-calculation-children  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'The ratio of adults to children is 5:3. There are 40 adults. Which calculation gives the number of children?', '5 parts are 40 adults, so one part is 40 ÷ 5 = 8, and children are 3 parts: 8 × 3 = 24. Dividing by 3 first finds the wrong part, multiplying by 5/3 scales the wrong way, and dividing by 8 uses the total number of parts instead of the adults'' parts.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-retention-not-equivalent-1-2  (band 1, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Spot the ratio that is not equivalent to 1:2.', '1:2 means the second amount is double the first, and 2:4, 3:6 and 5:10 all keep that relationship. In 2:3 the second number is not twice the first.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-sometimes-both-double  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'If one quantity doubles, does the other quantity always double?', 'Sometimes. In direct proportion it does: twice the rice serves twice the people. But in inverse proportion it halves: twice the workers take half the time. You have to know whether the relationship is direct or inverse.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- ratio-not-equivalent  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Which ratio is not equivalent to 3:4?', '6:8, 9:12 and 15:20 are 3:4 multiplied by 2, 3 and 5. 4:5 comes from adding 1 to each part, which changes the ratio: in 3:4 the second part is 4/3 of the first, and 5/4 is not 4/3.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- alg-five-more-than-n  (band 1, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'A pen costs n pence. A pencil costs 5p more than a pen. Which expression gives the cost of a pencil?', '"5 more than n" means add 5: n + 5. Writing 5n means 5 times n. "More than" is not a multiplication word, so it is not 5n, and it is not a subtraction either.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-divided-by-2  (band 2, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which expression means "a divided by 2"?', 'Dividing a by 2 is written a/2: the number being divided goes on top. Writing 2/a divides 2 by a, which is the other way round, and 2a multiplies instead of dividing.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-3a-as-sum  (band 2, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which expression is equal to 3a?', '3a means three lots of a, which is a + a + a. a × a × a is a³, not 3a. 3 + a and a + 3 mean 3 added to a, which is different: if a is 4, 3a is 12 but 3 + a is 7.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-simplify-5x-3y  (band 1, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify 5x + 3y.', '5x and 3y are not like terms: one is a number of x''s and the other a number of y''s, so they cannot be combined. The expression is already as simple as it gets. Adding the coefficients gives 8xy, which treats them as like terms.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-multiply-2a-3a  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify 2a × 3a.', '2a × 3a = 2 × a × 3 × a = 6 × a × a = 6a². Multiplying the coefficients (2 × 3 = 6) and the letters (a × a = a²) keeps them separate. Writing 6a adds the letters instead of multiplying, and 5a² adds the coefficients instead of multiplying.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-error-collecting  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Jaz writes 2a + 3b = 5ab. What has she done?', '2a and 3b are unlike terms, so 2a + 3b cannot be simplified. Jaz has combined the 2 and the 3 and joined the letters to get 5ab. If a and b were both 1, the expression would be 5 but 5ab would be 5 too — the error only shows with other values.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-substitute-3a  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of 3a when a = −2.', '3a means 3 × a, so 3 × (−2) = −6. The negative sign applies to the whole value, so the answer is negative. Adding instead of multiplying gives 3 + (−2) = 1, and 3 − 2 = 1 too.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-substitute-square  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of a² when a = −3.', 'a² means a × a, so (−3) × (−3) = 9. A negative times a negative is positive, so it is not −9. Multiplying by 2 instead of squaring gives −6.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-simplify-a-plus-a-squared  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify a + a².', 'a and a² are not like terms: one is a and the other is a × a. They cannot be collected, so the expression stays as a + a². Adding to get 2a² or 2a, or multiplying to get a³, all treat them as like terms.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-bridge-perimeter  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'A rectangle is a cm long and 3 cm wide. Which expression gives its perimeter in cm?', 'The perimeter is a + 3 + a + 3 = 2a + 6. a + 3 adds only one length and one width, and 3a multiplies instead of adding. 2a + 3 doubles the length but forgets to double the width.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-tick-equal-5a  (band 2, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Choose every expression equal to 5a.', '5a means five lots of a: a + a + a + a + a, which is also 5 × a, and 2a + 3a collects to 5a. 5 + a adds 5 to a, which is different, and a × a × a × a × a is a⁵.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-not-equal-3a-plus-2a  (band 2, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which expression is not equal to 3a + 2a?', '3a + 2a is 3 lots of a plus 2 lots of a, which is 5 lots of a: 5a, or a + a + a + a + a. 6a comes from multiplying the coefficients instead of adding them. 5 + a adds 5 to a, which is different.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-retention-not-equal-4x  (band 1, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Find the expression that is not equal to 4x.', '4x means four lots of x, so x + x + x + x, 4 × x and x × 4 all equal it. 4 + x adds 4 to x: if x = 3, then 4x is 12 but 4 + x is 7.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-substitute-two-terms  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of 2a + 3b when a = 5 and b = −2.', '2a = 2 × 5 = 10 and 3b = 3 × (−2) = −6, so 10 + (−6) = 4. Substituting only a gives 10 and ignores the second term. 16 treats b as +2, and −4 makes the 10 negative as well as the 6.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-sometimes-2a-means-2-times-a  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Does 2a always mean 2 × a?', 'Always. Writing a number next to a letter means they are multiplied, so 2a is 2 × a whatever a is. The letter stands for a number, not an object, so 2a is never "2 apples" as a separate thing.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-expand-4x-plus-5  (band 2, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'A drink costs (x + 5) pence. Four drinks cost 4(x + 5) pence. Expand 4(x + 5).', 'The 4 multiplies every term inside the bracket: 4 × x = 4x and 4 × 5 = 20, so 4(x + 5) = 4x + 20. Multiplying only the x by 4 gives 4x + 5, and adding 4 + 5 gives 4x + 9. Every term inside gets multiplied.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-minus-bracket-single  (band 2, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand −(x + 4).', 'The minus sign in front multiplies every term by −1: −(x + 4) = −x − 4. It does not only affect the x. −x + 4 changes the sign of the first term but not the second, and x − 4 or x + 4 drops the minus altogether.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-x-times-bracket  (band 2, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand x(x + 3).', 'The x multiplies both terms: x × x = x² and x × 3 = 3x, so x(x + 3) = x² + 3x. Multiplying only the first term gives x² + 3. x × 3x is 3x², not 3x² added to x², and x + 3x does not multiply the x by itself.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-collect-3x-plus-2  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand and simplify 3(x + 2) + 2x.', 'First expand: 3(x + 2) = 3x + 6, so the expression is 3x + 6 + 2x. Then collect the like terms: 3x + 2x = 5x, giving 5x + 6. Leaving 3x + 6 + 2x uncollected is not simplified; 5x + 8 multiplies the 2 by 3 as well as adding it.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-error-first-term  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Rob expands 5(x + 2) and writes 5x + 2. What has he done?', 'The 5 must multiply both terms: 5(x + 2) = 5x + 10. Rob multiplied the x by 5 but left the 2 as it was. The 2 was 2, and after multiplying by 5 it is 10.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-which-equivalent-2-3x-4  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Which expression is equivalent to 2(3x + 4)?', 'Multiply both terms by 2: 2 × 3x = 6x and 2 × 4 = 8, so 2(3x + 4) = 6x + 8. 6x + 4 multiplies only the first term, 5x + 8 adds 2 and 3 instead of multiplying, and 6x + 6 adds 2 and 4.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fac-fully-18x-plus-27  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Which expression is 18x + 27 fully factorised?', 'The highest common factor of 18 and 27 is 9, so 18x + 27 = 9(2x + 3). 3(6x + 9) is equivalent but not fully factorised: 3 can still come out of 6x + 9. 3(6x + 27) and 18(x + 27) do not multiply back to 18x + 27.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fac-2x-plus-4  (band 1, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Factorise 2x + 4.', 'Both terms divide by 2: 2x ÷ 2 = x and 4 ÷ 2 = 2, so 2x + 4 = 2(x + 2). Factorising is the inverse of expanding, so check by multiplying back: 2(x + 2) = 2x + 4. 2(x + 4) gives 2x + 8, and x(x + 4) is not equivalent.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-bridge-rectangle-area  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'A rectangle is (x + 5) cm long and 3 cm wide. Which expression gives its area in cm²?', 'Area is length × width, so it is 3(x + 5) = 3x + 15. The 3 multiplies both terms. 3x + 5 multiplies only the length term, and 3x + 8 adds the 3 and the 5 instead of multiplying.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-tick-equivalent-3-x-4  (band 3, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Select every expression equivalent to 3(x + 4).', '3(x + 4) = 3x + 12, and addition can be written in either order, so 12 + 3x is the same. The others multiply only the x by 3 and leave the 4 alone, or add instead of multiplying.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- exp-not-equivalent-4x-plus-8  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'One of these is not equivalent to 4x + 8. Which one?', '4(x + 2) = 4x + 8 and 2(2x + 4) = 4x + 8, so both are equivalent to 4x + 8. 4(x + 8) = 4x + 32, which is not.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-not-equivalent-6x-plus-12  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Which expression is not equivalent to 6x + 12?', '6(x + 2), 3(2x + 4) and 2(3x + 6) all multiply back to 6x + 12, even though they use different common factors. 12(x + 1) = 12x + 12, which is not the same.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-sometimes-factorising-changes-value  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Does factorising an expression change its value?', 'Never. Factorising is the inverse of expanding, and both maintain equivalence. 6x + 9 and 3(2x + 3) take the same value for every x, because 3(2x + 3) = 6x + 9. If the value changed, the factorisation would be wrong.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-retention-equal-2-x-1  (band 1, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Choose every expression equal to 2(x + 1).', '2(x + 1) means two lots of (x + 1), so it is x + 1 + x + 1 = 2x + 2. Multiplying only the x by 2 gives 2x + 1. Adding 2 + 1 gives 2x + 3, and x + 2 multiplies nothing by 2 except the 1.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- exp-3-times-2x-minus-5  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand 3(2x − 5).', 'Multiply both terms by 3: 3 × 2x = 6x and 3 × (−5) = −15, so the answer is 6x − 15. Leaving −5 unchanged gives 6x − 5, changing its sign gives 6x + 15, and multiplying only the second term gives 2x − 15.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- eq-bridge-taxi  (band 2, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'A taxi charges £5 plus £2 for each kilometre. A journey costs £13. How many kilometres was the journey?', 'The journey costs 2x + 5 = 13, where x is the number of kilometres. Subtract 5 from both sides: 2x = 8, then divide by 2: x = 4. Adding the 5 instead gives 9, and stopping at 2x = 8 gives 8 km instead of dividing by 2. 6.5 comes from dividing before subtracting.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-both-sides-5x  (band 2, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 5x = 2x + 9.', 'Subtract 2x from both sides: 3x = 9, so x = 3. Adding the x terms instead gives 7x = 9, which is why 9/7 appears. Stopping at 3x = 9 leaves x = 9, and dividing the wrong way gives 3/7.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-negative-solution  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve x + 5 = 2.', 'Subtract 5 from both sides: x = 2 − 5 = −3. A negative answer is a solution. Keeping the size and dropping the sign gives 3, adding instead of subtracting gives 7, and rejecting the answer as impossible is the misconception that equations must have positive solutions.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-fraction-coefficient-step  (band 2, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Which step solves x/3 = 4?', 'x is divided by 3, so undo it by multiplying both sides by 3: x = 12. Dividing again makes x smaller, and subtracting 3 treats the equation as "work out the answer" rather than keeping both sides equal.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-error-one-side  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Sam solves 4x − 5 = 27 and gets x = 5.5. Which mistake did Sam make?', 'Undo the − 5 first: 4x = 32, then divide by 4 to get x = 8. Sam divided 22 by 4 instead, working on the wrong side of the subtraction. Whatever is done must be done to the whole of both sides, in the reverse order to the one the expression was built in.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-error-order-inverse  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Lina solves 3x + 2 = 11 by working out (11 + 2) ÷ 3. What has she done?', 'Undo the + 2 by subtracting: 3x = 9, so x = 3. Lina used the inverse of the wrong sign, adding 2 to get 13. The operations must be undone in reverse order, each one by its inverse.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-error-divide-all  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'To solve (x + 4)/2 = 5, Priya writes x + 4 = 5/2. What has she done?', 'The whole left side is divided by 2, so undo it by multiplying both sides by 2: x + 4 = 10, so x = 6. Priya divided the right side as well, which makes it smaller instead of undoing the division. The same operation must be applied to the whole of both sides.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-bracket-solve  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 3(x − 2) = 9.', 'Either divide both sides by 3 first: x − 2 = 3, so x = 5; or expand: 3x − 6 = 9, so 3x = 15 and x = 5. Dividing only the x by 3 gives x = 1, and 3 is the value of x − 2, not of x.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-negative-both-sides  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 3x − 4 = x + 2.', 'Subtract x from both sides: 2x − 4 = 2. Add 4: 2x = 6, so x = 3. Adding the x terms instead gives 4x = 6, which leads to 1.5 or 1. Stopping at 2x = 6 gives 6, and a sign slip gives −3.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-tick-solution-4  (band 3, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every equation that has the solution x = 4.', 'Substitute x = 4 and check: 4 + 3 = 7, 2 × 4 = 8 and 4/2 = 2, so the first three work. x − 1 = 5 needs x = 6, and 3x = 15 needs x = 5. Substituting is the quickest check.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-solve-2-bracket-14  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 2(x + 3) = 14.', 'Divide both sides by 2: x + 3 = 7, so x = 4. Expanding first gives 2x + 6 = 14, then 2x = 8 and x = 4 as well. Subtracting 3 from 14 gives 11, which forgets the 2; and 2 is 7 − 5, not 7 − 3.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-first-step-5x-minus-3  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'What is the first step in solving 5x − 3 = 17?', 'The 3 was subtracted to build the expression, so undo it by adding 3 to both sides: 5x = 20, then x = 4. Subtracting 3 again takes it further from the answer, and dividing by 5 first leaves x − 3/5 on the left.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-retention-solution-5  (band 1, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Find every equation with the solution x = 5.', 'Check each by substituting 5: 5 + 2 = 7, 3 × 5 = 15 and 5 − 1 = 4 all work. 2x = 12 needs x = 6, and x + 5 = 5 needs x = 0.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-sometimes-one-solution  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Does an equation always have exactly one solution?', 'Sometimes. x + 5 = 2 has exactly one solution, x = −3, and x + 1 = x + 1 is true for every x, so it has infinitely many. An equation is a statement that two expressions are equal, and the number of values that make it true depends on the equation.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-not-solution-6  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Which equation does not have the solution x = 6?', 'Substitute x = 6: 6 + 2 = 8, 6/2 = 3 and 3 × 6 = 18 all work. 2x = 10 needs x = 5, not 6. Substituting is the quickest way to check.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-nth-term-5-9  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'What is the nth term of the sequence 5, 9, 13, 17, …?', 'The terms increase by 4, so the nth term starts with 4n. For n = 1 that gives 4, but the first term is 5, so add 1: 4n + 1. 4n − 1 starts at 3, n + 4 uses the term-to-term rule as the formula, and 5n starts at 5 but increases by 5.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-nth-term-2-5  (band 1, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence starts 2, 5, 8, 11, … and increases by 3 each time. Which is the nth term?', 'Increasing by 3 means the nth term contains 3n. With n = 1, 3n is 3, but the first term is 2, so subtract 1: 3n − 1. 3n + 2 starts at 5, and 3n starts at 3. n + 3 gives 4, 5, 6, …, which increases by 1, not 3.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-error-nth-term  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'Dan says the nth term of 4, 7, 10, 13, … is n + 3. What has he done?', 'The common difference is 3, so the nth term is 3n + 1: it gives 4, 7, 10, 13. Dan has written the term-to-term rule "add 3" as "n + 3", which gives 4, 5, 6, 7, … — starting at 4 but increasing by 1. You can check by substituting n = 2.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-square-numbers  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'The sequence 1, 4, 9, 16, 25, … has which nth term?', 'The terms are the square numbers: 1 × 1, 2 × 2, 3 × 3, so the nth term is n². 2n gives 2, 4, 6, 8, which is not the same sequence, and n + 3 gives 4, 5, 6, 7. The gaps between the terms increase, so no linear rule fits.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-doubling-next-term  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence begins 5, 10, 20, 40, … What is the next term?', 'Each term is double the one before, so the next is 80. A sequence does not have to add the same amount each time. 45 adds 5 as if the gap were constant, 60 adds 20, and 100 multiplies by something other than 2.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-decreasing-nth-term  (band 4, single_choice)
values ((select id from topics where slug = 'sequences'), 'What is the nth term of 20, 17, 14, 11, …?', 'The sequence decreases by 3, so the coefficient of n is −3, written as 23 − 3n: with n = 1 that gives 20, and n = 2 gives 17. A positive coefficient makes the sequence increase. 20 − 3n starts at 17, one step too low.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-is-100-a-term  (band 4, single_choice)
values ((select id from topics where slug = 'sequences'), 'The nth term of a sequence is 3n + 1. Is 100 a term of this sequence?', 'Solve 3n + 1 = 100: 3n = 99, so n = 33, a whole number, so 100 is the 33rd term. The 32nd term is 97 and the 34th is 103. A number is a term only when solving gives a whole-number n.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-fourth-term-from-formula  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'The nth term of a sequence is 5n − 2. What is the 4th term?', 'Substitute n = 4: 5 × 4 − 2 = 18. Forgetting the − 2 gives 20, adding instead of subtracting gives 22, and multiplying 5 by 4 then subtracting 2 the wrong way gives 3. The formula gives the term directly for any n.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tenth-from-fifth  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'A stack grows by 4 bricks each layer. The 5th layer has 16 bricks. How many bricks are in the 10th layer?', 'Five more layers, each 4 bricks bigger: 16 + 5 × 4 = 36. Doubling the 5th term gives 32, which assumes the 10th term is twice the 5th. That is only true in special sequences, and not here.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-missing-term  (band 1, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence is 4, 9, 14, __, 24, … What is the missing term?', 'The terms increase by 5 each time, so the missing term is 14 + 5 = 19, and 19 + 5 = 24 matches the next term given. 18 and 20 do not fit the gap from 14 to 24.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-bridge-tile-rows  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'A tile pattern has 3 tiles in row 1, 5 tiles in row 2, 7 tiles in row 3, and so on. How many tiles are in row 10?', 'The rule is 2n + 1: row 1 has 3, row 2 has 5, row 3 has 7. For row 10, 2 × 10 + 1 = 21. Using the term-to-term rule "add 2" as 3 × 10 gives 30, and 2n alone gives 20.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tick-constant-difference  (band 3, multi_select)
values ((select id from topics where slug = 'sequences'), 'Which sequences increase by the same amount each time?', 'A constant difference means adding the same number each time. 2, 5, 8, 11 adds 3; 10, 20, 30, 40 adds 10; and 100, 90, 80, 70 adds −10, which is still constant. 1, 2, 4, 8 and 5, 10, 20, 40 double, so their gaps grow.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-not-nth-term-3n  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'Find the sequence that does not have nth term 3n.', '3n gives the multiples of 3 starting at n = 1: 3, 6, 9, 12. The sequence 6, 9, 12, 15 is 3n + 3 and 0, 3, 6, 9 is 3n − 3, each shifted one step. 3, 9, 27, 81 multiplies by 3 each time, which grows far faster.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-retention-terms-of-5n  (band 1, multi_select)
values ((select id from topics where slug = 'sequences'), 'Tick the numbers that are terms of 5, 10, 15, 20, …', 'The terms are the multiples of 5, so 25, 35 and 50 are all terms and the sequence carries on for ever. 12 and 42 are not multiples of 5, so they never appear.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-sometimes-tenth-double-fifth  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'Is the 10th term of a sequence always twice the 5th term?', 'Sometimes. In 1, 2, 3, … the 5th term is 5 and the 10th is 10, so it holds. In 4, 7, 10, … the 5th term is 16 and the 10th is 31, so it does not. A property of one sequence is not a property of every sequence.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-table-to-equation  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A taxi costs £1 to book plus £3 for each kilometre. Which equation gives the cost y in pounds for x kilometres?', 'For x kilometres the cost is 3x, and the £1 booking adds on, so y = 3x + 1. Check it: 0 km costs £1 and 2 km costs £7. y = x + 3 adds 3 instead of multiplying by 3, and y = 3x − 1 subtracts the booking fee.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-gradient-and-intercept  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'For the line y = 5x − 3, what is the gradient and where does the line cross the y-axis?', 'In y = mx + c the gradient is m and the crossing point is (0, c). Here m = 5 and c = −3, so the gradient is 5 and the line crosses the y-axis at (0, −3). Swapping the 5 and the −3 confuses the gradient with the intercept.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-crossing-at-4  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which line crosses the y-axis at (0, 4)?', 'The line crosses the y-axis where x = 0, so the constant term is the y-value: (0, 4) needs c = 4. Only y = 2x + 4 has that. y = 4x + 2 crosses at (0, 2) and has gradient 4, and y = 4x also crosses at (0, 0).', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-coordinates-direction  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'What are the coordinates of the point that is 3 to the right of the origin and 2 below it?', 'Coordinates are written (x, y): 3 to the right is x = 3, and 2 below the origin is y = −2, so the point is (3, −2). Writing (−2, 3) swaps the order. 2 below the origin is negative, so (3, 2) is above the axis.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-gradient-calculation  (band 2, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which calculation gives the gradient of the line through (1, 2) and (4, 11)?', 'Gradient is the change in y divided by the change in x: (11 − 2) ÷ (4 − 1) = 9 ÷ 3 = 3. Dividing the other way up gives 1/3, adding instead of subtracting changes both values, and multiplying gives 27.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-negative-gradient  (band 4, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A line passes through (0, 5) and (2, 1). What is its gradient?', 'The gradient is (1 − 5) ÷ (2 − 0) = −4 ÷ 2 = −2. The line goes down from left to right, so the gradient must be negative. Dropping the sign gives 2, and other divisions give the wrong size.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-midpoint  (band 2, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'On a map a straight path runs from (2, 3) to (8, 11). A bench sits halfway along the path. What are the coordinates of the bench?', 'The midpoint is the average of the coordinates: ((2 + 8) ÷ 2, (3 + 11) ÷ 2) = (5, 7). Subtracting gives (6, 8), and adding without halving gives (10, 14). Halving 2 and 3 alone gives (1, 1.5), not (3, 4).', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-point-on-line  (band 4, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which point lies on the line y = 2x + 1?', 'Substitute each x: 2 × 1.5 + 1 = 4, so (1.5, 4) is on the line. A line is not only whole-number points. (2, 3) is wrong because 2 × 2 + 1 = 5, and (3, 5) uses 3 + 1 + 1 instead of 2 × 3 + 1.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-horizontal-line  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which line is horizontal?', 'y = 3 means every point on the line has y-value 3, whatever x is, so the line runs left to right and is horizontal. x = 3 is vertical, because every point has x-value 3. y = 3x and x + y = 3 both slope.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-tick-points-x-plus-2  (band 2, multi_select)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Find every point that lies on the line y = x + 2.', 'Substitute x into y = x + 2: (0, 2), (1, 3) and (4, 6) all work. (2, 3) would need 2 + 2 = 3, and (3, 6) would need 3 + 2 = 6. Add 2 to the x-value, do not multiply.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- grph-not-point-3x-minus-2  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which point is not on the line y = 3x − 2?', 'Work out 3x − 2 for each x: x = 0 gives −2, x = 1 gives 1 and x = 2 gives 4, so those three points are on the line. For (2, 6), 3 × 2 − 2 = 4, not 6.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-retention-on-x-axis  (band 1, multi_select)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Tick the points that lie on the x-axis.', 'On the x-axis the y-coordinate is 0, so (3, 0), (−5, 0) and the origin (0, 0) are all on it. (0, 2) is on the y-axis, and (2, 3) is in neither axis: the first number is the x-value.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- grph-equation-from-point-and-gradient  (band 4, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A line passes through (0, 5) and has gradient −2. Which is its equation?', 'The gradient is −2 and the line crosses the y-axis at (0, 5), so the equation is y = −2x + 5, written y = 5 − 2x. Swapping the gradient and intercept gives y = 5x − 2. y = −2x crosses at (0, 0), and y = 2x + 5 has the wrong sign on the gradient.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-substitute-4x-minus-1  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A line has equation y = 4x − 1. What is the value of y when x = 3?', 'Substitute x = 3: 4 × 3 − 1 = 11. Forgetting the − 1 gives 12, and adding it gives 13. 8 comes from 4 + 3 + 1 instead of 4 × 3 − 1.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-sometimes-integer-points  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Does a straight line pass through only points whose coordinates are whole numbers?', 'Never. A straight line is made of infinitely many points, and between any two whole-number points there are others such as (1.5, 4) on y = 2x + 1. Whole-number coordinates are convenient to plot, but they are not the whole line.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
