insert into topics (slug, name, description, sort_order) values
    ('place-value', 'Place value & ordering', 'Place value, ordering decimals and negative numbers.', 1),
    ('properties-of-number', 'Factors, multiples, primes, squares & cubes', 'Factors, multiples, primes, square and cube numbers, HCF and LCM.', 2),
    ('integers-and-decimals', 'Arithmetic with integers & decimals', 'Adding, subtracting, multiplying and dividing with integers and decimals.', 3),
    ('rounding-and-estimation', 'Rounding & estimation', 'Rounding to decimal places and significant figures, and estimating calculations.', 4),
    ('fractions', 'Fractions', 'Equivalent fractions, comparing, and adding, subtracting, multiplying and dividing fractions.', 5),
    ('fractions-decimals-percentages', 'Fractions, decimals & percentages', 'Converting between fractions, decimals and percentages, and percentage change.', 6),
    ('ratio-and-proportion', 'Ratio & proportion', 'Ratio notation and sharing in a ratio, direct and inverse proportion.', 7),
    ('expressions-and-simplifying', 'Expressions & simplifying', 'Algebraic notation, collecting like terms and substitution.', 8),
    ('expanding-and-factorising', 'Expanding & factorising', 'Expanding brackets and taking out common factors.', 9),
    ('solving-equations', 'Solving linear equations', 'Solving linear equations, including unknowns on both sides.', 10),
    ('sequences', 'Sequences', 'Term-to-term rules and the nth term, including decreasing and geometric sequences.', 11),
    ('coordinates-and-linear-graphs', 'Coordinates & linear graphs', 'Coordinates, midpoints, gradient and the equation of a straight line.', 12)
